'use client'

import { type LucideIcon } from 'lucide-react'
import { ReactNode } from 'react'

import { cn } from '@/lib/utils'

export const KPIValue = ({
  children,
  className = '',
}: {
  children: ReactNode
  className?: string
}) => {
  return <div className={`text-3xl font-bold ${className}`}>{children}</div>
}

export const KPIIcon = ({
  className = '',
  icon: Icon,
}: {
  className?: string
  icon: LucideIcon
}) => {
  return (
    <div
      className={cn(
        'flex items-center justify-center rounded-md bg-muted p-3 aspect-square w-12',
        className,
      )}
    >
      <Icon />
    </div>
  )
}

// Chart components have been moved to @/registry/components/dashboardblocks/chart
// Exporting for backward compatibility
export {
  TinyBarChart as KPIBarChart,
  TinyLineChart as KPILineChart,
  TinyAreaChart as KPIAreaChart,
  type TinyBarChartProps as KPIBarChartProps,
  type TinyLineChartProps as KPILineChartProps,
  type TinyAreaChartProps as KPIAreaChartProps,
} from '@/registry/components/dashboardblocks/chart'
